package com.shalab.calculator.engineering;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class EngineeringCalculatorTest {@Test void electricalAndPhysics(){assertEquals(20,EngineeringCalculator.voltage(2,10));assertEquals(60,EngineeringCalculator.powerVI(12,5));assertEquals(6,EngineeringCalculator.series(1,2,3));assertEquals(2,EngineeringCalculator.parallel(3,6));assertEquals(2,EngineeringCalculator.force(1,2));assertEquals(25,EngineeringCalculator.kineticEnergy(2,5));assertEquals(2,EngineeringCalculator.density(10,5));}
 @Test void solvesRealAndComplexQuadratics(){var roots=EngineeringCalculator.solveQuadratic(1,-5,6);assertEquals(1,roots.discriminant());assertEquals("3.0",roots.first());assertEquals("2.0",roots.second());var complex=EngineeringCalculator.solveQuadratic(1,0,1);assertTrue(complex.first().contains("i"));assertThrows(IllegalArgumentException.class,()->EngineeringCalculator.solveQuadratic(0,1,1));}
 @Test void errorCalculationsAndValidation(){assertEquals(2,EngineeringCalculator.absoluteError(12,10));assertEquals(.2,EngineeringCalculator.relativeError(12,10));assertEquals(20,EngineeringCalculator.percentageError(12,10));assertThrows(IllegalArgumentException.class,()->EngineeringCalculator.density(1,0));}}
